import React from 'react';
import { MapContainer, TileLayer, Polyline } from 'react-leaflet';
import 'leaflet/dist/leaflet.css';
import L from 'leaflet';

// This fixes a known issue with Leaflet and React where marker icons don't appear.
delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
    iconRetinaUrl: require('leaflet/dist/images/marker-icon-2x.png'),
    iconUrl: require('leaflet/dist/images/marker-icon.png'),
    shadowUrl: require('leaflet/dist/images/marker-shadow.png'),
});

const TripMap = ({ gpsData, columns }) => {

    // --- FIX: Safely find column names ---
    // If columns is not an array, or if the names aren't found, these will be null.
    const latCol = columns?.find(c => c.toLowerCase().includes('latitude'));
    const lonCol = columns?.find(c => c.toLowerCase().includes('longitude'));

    // --- FIX: Check for required data before processing ---
    // If we don't have GPS data or the necessary columns, we can't render a map.
    if (!gpsData || gpsData.length === 0 || !latCol || !lonCol) {
        return <div style={{ padding: '20px', textAlign: 'center', backgroundColor: '#f0f0f0' }}>No GPS data available for this trip.</div>;
    }

    // Filter out any invalid points just in case
    const validGpsData = gpsData.filter(p => p[latCol] != null && p[lonCol] != null && p[latCol] !== 0 && p[lonCol] !== 0);

    if (validGpsData.length === 0) {
        return <div style={{ padding: '20px', textAlign: 'center', backgroundColor: '#f0f0f0' }}>No valid GPS coordinates found.</div>;
    }

    const primaryPath = validGpsData.map(p => [p[latCol], p[lonCol]]);

    const getBounds = () => {
        if (!primaryPath || primaryPath.length === 0) {
            // Default to a central US view if something goes wrong
            return [[39.8283, -98.5795], [39.8283, -98.5795]];
        }
        // This logic is now safe because we know primaryPath is a valid array.
        const latitudes = primaryPath.map(p => p[0]);
        const longitudes = primaryPath.map(p => p[1]);

        return [
            [Math.min(...latitudes), Math.min(...longitudes)],
            [Math.max(...latitudes), Math.max(...longitudes)]
        ];
    };

    const bounds = getBounds();

    return (
        <MapContainer bounds={bounds} style={{ height: '400px', width: '100%' }}>
            <TileLayer
                url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
                attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
            />
            <Polyline pathOptions={{ color: 'blue' }} positions={primaryPath} />
        </MapContainer>
    );
};

export default TripMap;
